#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Stop hook — 任务推进出口门 (zmd / zhuran24)

落地: ~/.claude/settings.json 的 hooks.Stop:
  {"hooks": {"Stop": [{"hooks": [
     {"type": "command",
      "command": "python \"C:\\\\Users\\\\22957\\\\.claude\\\\hooks\\\\stop_gate.py\""}
  ]}]}}

契约 (Claude Code Stop hook):
  - stdin: JSON {session_id, transcript_path, stop_hook_active, hook_event_name, cwd?}
  - 放行: 退出码 0, stdout 空 或 {"decision":"allow"} (这里输出空)
  - 拦截: stdout 输出 {"decision":"block","reason":"..."} (退出码 0)
            reason 会被回灌给模型, 驱动它继续干活

设计铁律: 保守优先 —— 任何不确定一律 ALLOW; 宁可漏拦, 绝不误拦把用户卡住。
一键停: env ZMD_STOP_GATE_DISABLE=1 或 flag 文件 (见 KILL_SWITCH)。
"""
import json
import os
import re
import sys
from pathlib import Path

# ---------------- helpers: 永远不抛, 出错即放行 ----------------

def _allow():
    # stdout 空 = 放行
    sys.exit(0)

def _block(reason: str):
    sys.stdout.write(json.dumps({"decision": "block", "reason": reason},
                                ensure_ascii=False))
    sys.exit(0)

def _truthy_env(name: str) -> bool:
    v = os.environ.get(name, "").strip().lower()
    return v in ("1", "true", "yes", "on")

def _home() -> Path:
    try:
        return Path(os.path.expanduser("~"))
    except Exception:
        return Path(".")

# ---------------- kill switch / goal-active gate ----------------

def kill_switch_on(cwd: Path) -> bool:
    if _truthy_env("ZMD_STOP_GATE_DISABLE"):
        return True
    for p in (_home() / ".claude" / "zmd_stop_gate.off",
              _home() / "zmd_stop_gate.off",
              cwd / ".zmd_stop_gate.off"):
        try:
            if p.exists():
                return True
        except Exception:
            return True  # 连判断都出错 → 倒向停用
    return False

def goal_active(cwd: Path) -> bool:
    if _truthy_env("ZMD_STOP_GATE_GOAL_ACTIVE"):
        return True
    for p in (_home() / ".claude" / "zmd_active_goal",
              cwd / ".zmd_active_goal"):
        try:
            if p.exists() and p.stat().st_size > 0:
                return True
        except Exception:
            pass
    return False

# ---------------- transcript 读取 ----------------

def last_assistant(transcript_path: str):
    """返回 (text:str, has_tool_use:bool) 或 None."""
    try:
        p = Path(transcript_path)
        if not p.exists():
            return None
        lines = p.read_text(encoding="utf-8", errors="replace").splitlines()
    except Exception:
        return None
    for raw in reversed(lines):
        raw = raw.strip()
        if not raw:
            continue
        try:
            rec = json.loads(raw)
        except Exception:
            continue
        msg = rec.get("message", rec)
        if not isinstance(msg, dict):
            continue
        if msg.get("role") != "assistant":
            continue
        content = msg.get("content")
        text_parts, has_tool = [], False
        if isinstance(content, str):
            text_parts.append(content)
        elif isinstance(content, list):
            for blk in content:
                if not isinstance(blk, dict):
                    continue
                t = blk.get("type")
                if t == "text" and isinstance(blk.get("text"), str):
                    text_parts.append(blk["text"])
                elif t in ("tool_use", "server_tool_use"):
                    has_tool = True
        return ("\n".join(text_parts), has_tool)
    return None

# ---------------- 句法判定 ----------------

def tail_segment(text: str) -> str:
    """取结尾段: 末尾 ~200 字符窗口里的最后 1-2 句."""
    t = text.rstrip()
    if not t:
        return ""
    window = t[-200:]
    parts = re.split(r"[。!?！？；;\n]", window)
    parts = [s for s in parts if s.strip()]
    return "".join(parts[-2:]) if parts else window

# 合法终态宽豁免 (扫全文, 看起来像就放行)
EXEMPT = {
    "WAITING_EXTERNAL": re.compile(
        r"(在等|等待|跑完|后台运行|已在后台|完成后(会)?(唤醒|通知)|"
        r"等[^。\n]{0,8}(回复|交付|结果|跑完|完成)|run_in_background|"
        r"尚未跑完|还在跑|跑着|等它跑)"),
    "BLOCKED_USER_ONLY": re.compile(
        r"((已(完成|做完|跑完|改完|推送|落地)|我已经)[^。\n]{0,60}"
        r"(只剩|仅剩|唯一只有你|这点只有你))|外部账目|手动计数|"
        r"(不可逆[^。\n]{0,12}(高风险|你拍板|你确认))|客服回执"),
    "TECHNICAL_HANDOFF": re.compile(
        r"(需要你(手动)?(重启|在BIOS|在系统里|插拔|手动点|手动操作)|"
        r"权限(被拒|不足)|工具(报错|失败|不可用)|环境(限制|边界)|"
        r"harness\s*限制|只能你手动|无法自行(继续|完成))"),
}

# 元讨论豁免 (在复述规则/写 hook 本身, 不是在犯)
META = re.compile(r"(判据|规则|例外|CLAUDE\.md|记忆树|hook|非法句式|本门|出口门)")

# 非法模式 (只在结尾段上跑)
ILLEGAL = [
    ("trailing_question_offer", re.compile(
        r"(要不要|需不需要|要我|需要我|用不用|是否需要|是否(要|希望我)|"
        r"我可以(帮你|帮您)?[^。\n]{0,12}吗)[^。\n]{0,40}[?？]?\s*$")),
    ("you_decide", re.compile(
        r"(你来定|你定|由你定|你说了算|你的\s*call|看你的call|"
        r"等你(裁决|定夺|拍板|决定|确认|指示|发话)|"
        r"看你(的)?(意思|想法)|听你的|你裁决)")),
    ("pace_kicked_back", re.compile(
        r"(节奏|进度|排程|额度|并发|批次|批量|要发几个|发几条|什么时候发|"
        r"现在还是等会|快慢)[^。\n]{0,16}"
        r"(你来|你定|由你|你说|是你的|交给你|你决定|你把控)")),
    ("conditional_kickback", re.compile(
        r"(你(给|说|确认|批|点头|发话|同意)[^。\n]{0,20}"
        r"我(就|再|来|会|马上|立刻))|"
        r"(等你(确认|点头|发话|说一声)[^。\n]{0,12}我(就|再))")),
    ("announce_next_no_action", re.compile(
        r"(我现在(就)?(去|来|开始)|接下来我(去|来|会|要|处理|做|改|跑|发|写|查)|"
        r"下一步我(去|来|会|要|处理|做)|我这就(去|来)|那我(去|来|开始))"
        r"[^。\n]{0,30}")),
    ("self_imposed_conservatism", re.compile(
        r"(保险起见|稳妥起见|稳一点|谨慎起见|为了安全)[^。\n]{0,20}"
        r"(先(发|做|跑|试)|只(发|做|跑)|小批|分批|限并发|一个一个|逐个先)")),
    ("permission_to_proceed", re.compile(
        r"(我可以(开始|继续|动手|往下)了吗|这样(可以|行|对)吗|可以了吗|"
        r"然后呢[?？]?\s*$|接下来呢[?？]?\s*$|"
        r"你看(这样)?(行不行|可以吗|如何))\s*[?？]?\s*$")),
]

FEEDBACK_TAIL = (
    "active goal 未完成且你还有自己能执行的 next action —— 当场做掉, "
    "不准以请示/宣告下一步收尾。若真在等外部结果或只剩用户能定的残余, "
    "请显式说清在等什么 / 只剩哪点是用户的。")

# ---------------- 主流程 ----------------

def main():
    try:
        data = json.load(sys.stdin)
    except Exception:
        _allow()

    if data.get("hook_event_name") and data.get("hook_event_name") != "Stop":
        _allow()

    # 防死循环硬闸
    if data.get("stop_hook_active"):
        _allow()

    try:
        cwd = Path(data.get("cwd") or os.getcwd())
    except Exception:
        cwd = Path(".")

    if kill_switch_on(cwd):
        _allow()

    # 门默认睡着: 没有明确 active goal 信号就放行
    if not goal_active(cwd):
        _allow()

    tp = data.get("transcript_path")
    if not tp:
        _allow()
    got = last_assistant(tp)
    if got is None:
        _allow()
    text, has_tool = got

    # 还在调工具收尾 = 在干活
    if has_tool:
        _allow()
    if not text or not text.strip():
        _allow()

    # 合法终态宽豁免 (全文)
    for rgx in EXEMPT.values():
        if rgx.search(text):
            _allow()

    tail = tail_segment(text)
    if not tail:
        _allow()

    # 元讨论豁免
    if META.search(tail):
        _allow()

    hits = [name for name, rgx in ILLEGAL if rgx.search(tail)]
    if not hits:
        _allow()

    reason = ("检测到回合以这类模式收尾: " + ", ".join(hits) + "。" + FEEDBACK_TAIL)
    _block(reason)


if __name__ == "__main__":
    try:
        main()
    except SystemExit:
        raise
    except Exception:
        # 任何意外 → 放行, 绝不卡用户
        _allow()
